  id bigint, name text, category text, price integer, old_price integer,
  sizes text[], color text, badge text, rating numeric, description text, image text
)
on conflict (id) do update set
  name = excluded.name, category = excluded.category, price = excluded.price,
  old_price = excluded.old_price, sizes = excluded.sizes, color = excluded.color,
  badge = excluded.badge, rating = excluded.rating, description = excluded.description,
  image = excluded.image;

select setval(pg_get_serial_sequence('public.products', 'id'), (select max(id) from public.products), true);
